extern int far _fmemcmp(const void far *, const void far *, unsigned int);
extern void far *_fmemcpy(void far *, const void far *, unsigned int);
void far f(unsigned char far *oldLine, unsigned char far *newLine, unsigned int n) {
    if (_fmemcmp(oldLine, newLine, n) != 0)
        _fmemcpy(oldLine, newLine, n);
}
